var test = require('node:test');
var assert = require('node:assert');
var path = require('node:path');

// The real mendel-middleware needs a running Mendel daemon. Stub it out so we
// can exercise the app's visitorId middleware in isolation.
var mwPath = require.resolve('mendel-middleware');
require.cache[mwPath] = {
    id: mwPath,
    filename: mwPath,
    loaded: true,
    exports: function () {
        return function (req, res, next) {
            req.mendel = {
                isSsrReady: function () {
                    return false;
                },
                getURL: function (bundle) {
                    return '/client/' + bundle + '.js';
                },
            };
            next();
        };
    },
};

process.env.NODE_ENV = 'production';
var app = require('../app');

function request(query) {
    var req = {
        url: '/',
        method: 'GET',
        query: query || {},
        cookies: {},
    };
    var body = '';
    var cookies = [];
    var res = {
        cookie: function (name, value) {
            cookies.push({ name: name, value: value });
        },
        send: function (chunk) {
            body += chunk;
            return this;
        },
        end: function () {
            return this;
        },
    };
    app(req, res);
    return { body: body, cookies: cookies, req: req };
}

test('assigns a new visitorId when none is present', function () {
    var result = request({ ssr: 'false' });
    var visitorId = result.req.visitorId;
    assert.ok(visitorId, 'visitorId should be set');
    assert.match(
        visitorId,
        /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i,
        'visitorId should be a UUID, got: ' + visitorId
    );
    var cookie = result.cookies.find(function (c) {
        return c.name === 'visitorId';
    });
    assert.ok(cookie, 'visitorId cookie should be set');
    assert.strictEqual(cookie.value, visitorId);
});

test('reuses an existing visitorId cookie', function () {
    var existing = '8417bb0e-d918-4807-b9a3-0339c6300d4f';
    var req = {
        url: '/',
        method: 'GET',
        query: { ssr: 'false' },
        cookies: { visitorId: existing },
    };
    var res = {
        cookie: function () {},
        send: function () {
            return this;
        },
        end: function () {
            return this;
        },
    };
    app(req, res);
    assert.strictEqual(req.visitorId, existing);
});

